const boards = [
  { board: 'Wellfound',  searchUrl: 'https://wellfound.com/jobs?query=AI%20intern' },
  { board: 'Built In',   searchUrl: 'https://builtin.com/jobs?search=AI%20intern' },
  { board: 'Shine',      searchUrl: 'https://www.shine.com/job-search/ai-intern-jobs' },
  { board: 'Jobfound',   searchUrl: 'https://jobfound.app/jobs?search=AI' },
  { board: 'Himalayas',  searchUrl: 'https://himalayas.app/jobs/ai' },
  { board: 'Cutshort',   searchUrl: 'https://cutshort.io/jobs/ai-intern-jobs' },
  { board: 'HiringCafe', searchUrl: 'https://hiring.cafe/jobs?search=AI' },
  { board: 'LinkedIn Jobs', searchUrl: 'https://www.linkedin.com/jobs/search/?keywords=AI%20intern' }
];
// NEVER Internshala — deliberately not in this list.
return boards.map(b => ({ json: b }));

// Parse each board page (JSON first, then link scraping fallback).
// Filters: fitting role keywords + paid only. Never invents a role.
const FIT = /ai agent|ai engineer|software developer|machine learning|gen ?ai|llm|agentic|full stack/i;
const UNPAID = /unpaid|no stipend|volunteer/i;
const out = [];
for (const item of $input.all()) {
  const board = item.json.board || 'unknown';
  const raw = typeof item.json.data === 'string' ? item.json.data : JSON.stringify(item.json.data || item.json);
  let roles = [];
  try {
    const parsed = JSON.parse(raw);
    const arr = Array.isArray(parsed) ? parsed : (parsed.jobs || parsed.results || parsed.data || []);
    roles = arr.map(r => ({ title: r.title || r.name || '', company: r.company || r.companyName || '', url: r.url || r.link || '', stipend: r.stipend || r.salary || '' }));
  } catch (e) {
    const links = [...raw.matchAll(/<a[^>]+href=\"([^\"]+)\"[^>]*>([^<]{5,120})<\/a>/g)];
    roles = links.map(m => ({ title: m[2].trim(), company: '', url: m[1], stipend: '' }));
  }
  for (const r of roles) {
    if (!FIT.test(r.title)) continue;
    if (UNPAID.test(r.title + ' ' + (r.stipend || ''))) continue;
    out.push({ json: { board, title: r.title, company: r.company || 'unknown', url: r.url, stipend: r.stipend || '' } });
  }
}
return out;

// Dedupe parsed roles against the Applied Log sheet (company + title).
const parsed = $('Parse & Filter Roles').all().map(i => i.json);
const applied = new Set($input.all().map(i => ((i.json.Company || i.json.company || '') + '|' + (i.json.Role || i.json.role || '')).toLowerCase()));
const fresh = parsed.filter(r => !applied.has(((r.company || '') + '|' + (r.title || '')).toLowerCase()));
return fresh.map(r => ({ json: r }));

// Parse the agent JSON; on failure keep the role with score 0 so it is skipped, never guessed.
const raw = $input.first().json.output || $input.first().json.text || '';
const prev = $('Split In Batches').first().json;
let p = {};
try { p = JSON.parse(raw); } catch (e) {
  const m = String(raw).match(/\{[\s\S]*\}/);
  try { p = m ? JSON.parse(m[0]) : {}; } catch (e2) { p = {}; }
}
return [{ json: { ...prev, score: typeof p.score === 'number' ? p.score : 0,
  fitReason: p.fitReason || 'Could not parse agent output',
  resumeBullets: p.resumeBullets || [], coverLetter: p.coverLetter || '',
  recommendation: p.recommendation || 'skip' } }];

// Build the tailored resume bullets + cover letter as one text file.
const j = $input.first().json;
const text = [
  'Sivasai Boggu — Tailored Application',
  'Role: ' + j.title + ' at ' + j.company + ' (' + j.board + ')',
  'Listing: ' + j.url,
  'Fit score: ' + j.score + '/100 — ' + j.fitReason,
  '',
  'Tailored resume bullets:',
  ...(j.resumeBullets || []).map(b => '- ' + b),
  '',
  'Cover letter:',
  j.coverLetter || '',
  '',
  'Sivasai Boggu | sivasaiboggu@gmail.com | +91 9573719115 | Gooty, Andhra Pradesh',
  'BTech CS, IIIT Kottayam (2023-2027) | CGPA 7.73 | Available immediately'
].join('\n');
return [{ json: { ...j, packText: text,
  fileName: ('Tailored-' + (j.company || 'company') + '-' + (j.title || 'role')).replace(/[^A-Za-z0-9-]+/g, '-') + '.txt' } }];

