// Parse a Telegram callback_query into an action + the role it refers to.
// The callback message text carries the role title/company/listing URL.
const u = $input.first().json;
const cb = u.callback_query || {};
const msg = (cb.message && cb.message.text) || '';
const action = cb.data || '';
const lines = msg.split('\n');
const titleLine = lines.find(l => l.includes(' at ')) || '';
const urlLine = lines.find(l => l.startsWith('Listing: ')) || '';
return [{ json: { action, chatId: (cb.message && cb.message.chat && cb.message.chat.id) || 'YOUR_TELEGRAM_CHAT_ID',
  callbackId: cb.id || '', titleLine, url: urlLine.replace('Listing: ', '').trim(),
  messageText: msg } }];

